using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System.Collections.Concurrent;
using System.Threading.Tasks;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
var app = builder.Build();
app.MapControllers();
app.Run();

[ApiController]
[Route("api/[controller]")]
public class PromotionController : ControllerBase
{
    // In-memory store for promotional code redemptions
    private static ConcurrentDictionary<string, int> _promoUsage = new();
    private static readonly int MAX_REDEMPTIONS = 1;
    private static readonly object _lockObj = new();

    // Simulated reward credit
    private static ConcurrentDictionary<string, decimal> _userBalances = new();

    [HttpPost("redeem")]
    public async Task<IActionResult> RedeemPromo([FromBody] RedeemRequest request)
    {
        if (string.IsNullOrEmpty(request.PromoCode) || string.IsNullOrEmpty(request.UserId))
            return BadRequest("Missing required fields");

        // Check current usage count
        var currentUsage = _promoUsage.GetOrAdd(request.PromoCode, 0);

        if (currentUsage >= MAX_REDEMPTIONS)
        {
            return Conflict(new { error = "Promotion already fully redeemed" });
        }

        // Simulate async validation (e.g., checking promo validity against external service)
        await Task.Delay(50); // External API call latency

        // TOCTOU: Re-read and increment are not atomic
        var updatedUsage = _promoUsage.GetOrAdd(request.PromoCode, 0);
        if (updatedUsage >= MAX_REDEMPTIONS)
        {
            return Conflict(new { error = "Promotion already fully redeemed" });
        }

        // Increment usage - race window between check and update
        _promoUsage[request.PromoCode] = updatedUsage + 1;

        // Credit the user
        _userBalances.AddOrUpdate(request.UserId, 50.00m, (key, old) => old + 50.00m);

        return Ok(new { 
            message = "Promo redeemed successfully", 
            credit = 50.00m,
            userId = request.UserId 
        });
    }

    [HttpGet("balance/{userId}")]
    public IActionResult GetBalance(string userId)
    {
        var balance = _userBalances.GetOrAdd(userId, 0m);
        return Ok(new { userId, balance });
    }
}

public class RedeemRequest
{
    public string PromoCode { get; set; }
    public string UserId { get; set; }
}
